using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: Default discriminator property renamed from
        // "Discriminator" to "$type". Preserve the old name so existing
        // documents are still found.
        modelBuilder.Entity<Blog>().HasDiscriminatorInJsonProperty("Discriminator");

        // Breaking change 2: Default id format changed from
        // "EntityType|Key" to just "Key". Preserve the old format so
        // existing documents (e.g. "Blog|1") are still addressable.
        modelBuilder.Entity<Blog>().HasIdProperty(
            b => b.Id,
            idBuilder => idBuilder.HasDiscriminatorPrefix());

        // Breaking change 3: HasIndex() now throws for Cosmos provider
        // because Cosmos DB does not support EF-managed indexes.
        // Removed: modelBuilder.Entity<Blog>().HasIndex(b => b.Name);
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

